// DEV_RIO_101 Evidence Build — dry-run
// 実運用では上流(需要調査/MCP/検索)から差し込む。dry-runでは未取得は unknown。
// schemas/evidence_pack.schema.json 準拠。推定/実測/unknown を分離。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  theme: i.theme ?? '店舗の固定費/決済手数料の見直し',
  audience: i.audience ?? '小規模店舗経営者(飲食・美容)',
  raw_sources: i.raw_sources ?? []
} }];

// Evidence Pack 組み立て。未取得の事実は source_type='unknown'（捏造しない）。
const o = $input.first().json;
const execId = $execution?.id ?? 'dryrun';
const facts = (o.raw_sources && o.raw_sources.length)
  ? o.raw_sources.map(s => ({ claim: s.claim, value: s.value ?? null, source_type: s.source_type ?? 'unknown', source_url: s.source_url ?? null }))
  : [{ claim: '需要・競合・報酬条件は未取得', value: null, source_type: 'unknown', source_url: null }];
return [{ json: {
  evidence_pack_id: 'ev-' + execId,
  experiment_id: o.experiment_id,
  sources: (o.raw_sources || []).map(s => s.source_url).filter(Boolean),
  facts,
  notes: 'dry-run。実運用ではDEV_RIO_101が需要調査結果を投入。',
  assets: []
} }];
